#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

i128 rek(int64 x) {
    if (x <= 0) return 0;

    i128 result = 0;
    for (int64 power = 1; power <= x; ) {
        int64 quotient = x / power;
        result += static_cast<i128>(power) * ((quotient + 1) / 2);

        if (power > x / 2) break;
        power *= 2;
    }
    return result;
}

void print(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

